def evaluate(expr):
    if isinstance(expr, int):
        return expr
    elif expr[0] == '+':
        return evaluate(expr[1]) + evaluate(expr[2])
    elif expr[0] == '*':
        return evaluate(expr[1]) * evaluate(expr[2])

